let sessionToken=localStorage.getItem('typing-session')||'';
const gate=document.createElement('section');gate.id='auth';gate.className='screen';gate.innerHTML='<div class="card launch"><h1>Typing Express</h1><p>Tu pista empieza aquí.</p><form id="authForm"><label for="authUser">Usuario</label><input id="authUser" autocomplete="username" maxlength="20" required><small id="userAvailability" role="status" aria-live="polite"></small><label for="authPass">Contraseña</label><input id="authPass" type="password" autocomplete="current-password" inputmode="numeric" maxlength="6" required><small id="passHint">Contraseña de 6 dígitos</small><p id="authError" role="alert"></p><button id="loginBtn" class="primary" type="submit">Iniciar sesión</button><button id="registerBtn" type="button">Registrarse</button></form></div>';document.querySelector('header').after(gate);
let registering=false;const modal=document.createElement('dialog');modal.id='unknownUser';modal.innerHTML='<p>Ese usuario no existe.</p><p>¿Quieres registrarte?</p><button id="modalRegister">Registrarse</button><button id="modalCancel">Cancelar</button>';document.body.append(modal);function registrationMode(on){registering=on;$('authUser').maxLength=on?10:20;$('authUser').minLength=on?6:1;$('authUser').pattern=on?'[A-Za-z0-9_]{6,10}':'.*';$('loginBtn').textContent=on?'Registrarse':'Iniciar sesión';$('registerBtn').textContent=on?'Volver a iniciar sesión':'Registrarse';$('authPass').value='';passwordMode();scheduleAvailability(true)}function passwordMode(){$('authPass').inputMode='numeric';$('authPass').maxLength=6;$('authPass').pattern='[0-9]{6}';$('passHint').textContent='Contraseña de 6 dígitos'}passwordMode();$('authPass').oninput=()=>{$('authPass').value=$('authPass').value.replace(/[^0-9]/g,'').slice(0,6)};$('modalCancel').onclick=()=>modal.close();$('modalRegister').onclick=()=>{modal.close();registrationMode(true);$('authPass').focus()};

let availabilityTimer, availabilityVersion=0;
function scheduleAvailability(immediate=false){clearTimeout(availabilityTimer);const version=++availabilityVersion;const el=$('userAvailability');el.textContent='';el.style.color='';if(!registering)return;const name=$('authUser').value.trim();if(!/^[A-Za-z0-9_]{6,10}$/.test(name)){el.textContent='Usa entre 6 y 10 letras, números o guion bajo';return}const run=async()=>{try{const {data,error}=await db.rpc('usuario_disponible',{p_usuario:name});if(version!==availabilityVersion||!registering)return;if(error||typeof data!=='boolean'){el.textContent='';return}el.textContent=data?'Disponible':'Ese usuario ya existe';el.style.color=data?'#167342':'#bb253c'}catch{if(version===availabilityVersion)el.textContent=''}};if(immediate)run();else availabilityTimer=setTimeout(run,5000)}
$('authUser').addEventListener('input',()=>scheduleAvailability());
const account=document.createElement('div');account.innerHTML='<p>Corredor: <strong id="accountName"></strong></p>';$('menu').prepend(account);
$('nickname').readOnly=true;
function setIdentity(p){profile=p;$('nickname').value=p.username;$('accountName').textContent=p.username;refreshBest();$('logout').hidden=false;resetIdle()}
async function loadProfile(){const {data,error}=await db.rpc('mi_perfil',{p_token:sessionToken});if(error)throw error;if(!data?.length)return false;setIdentity(data[0]);return true}
function needAuth(message=''){$('logout').hidden=true;idleSince=0;profile=null;sessionToken='';localStorage.removeItem('typing-session');showScreen('auth');$('authError').textContent=message}
async function authenticate(register){$('authError').textContent='';if(register&&!/^[0-9]{6}$/.test($('authPass').value)){$('authError').textContent='La contraseña debe ser de 6 dígitos';return;}$('loginBtn').disabled=$('registerBtn').disabled=true;try{const {data,error}=await db.rpc(register?'registrar':'iniciar_sesion',{p_usuario:$('authUser').value.trim(),p_password:$('authPass').value});if(error)throw error;sessionToken=data[0].token;localStorage.setItem('typing-session',sessionToken);$('authPass').value='';if(await loadProfile())showScreen('menu');else needAuth('Vuelve a iniciar sesión.')}catch(e){if(!register&&e.message==='El usuario no existe'){modal.showModal();return;}$('authError').textContent=e.message||'No pudimos conectar. Intenta otra vez.'}finally{$('loginBtn').disabled=$('registerBtn').disabled=false}}
$('authForm').onsubmit=e=>{e.preventDefault();authenticate(registering)};$('registerBtn').onclick=()=>registrationMode(!registering);
const IDLE_LIMIT=10*60*1000;let idleSince=0,wasPlaying=false,loggingOut=false;
function isPlaying(){return phase==='running'||phase==='countdown'}
function resetIdle(){idleSince=Date.now()}
async function logoutSession(inactive=false){if(loggingOut)return;loggingOut=true;const token=sessionToken;try{await home();needAuth(inactive?'Se cerró la sesión por inactividad':'');if(token)await db.rpc('cerrar_sesion',{p_token:token})}finally{loggingOut=false}}
function checkIdle(){if(!profile||!sessionToken||loggingOut)return;const playing=isPlaying();if(playing){wasPlaying=true;resetIdle();return}if(wasPlaying){wasPlaying=false;resetIdle();return}if(idleSince&&Date.now()-idleSince>=IDLE_LIMIT)logoutSession(true)}
$('typing').addEventListener('input',()=>{if(isPlaying())resetIdle()});
setInterval(checkIdle,1000);document.addEventListener('visibilitychange',checkIdle);window.addEventListener('focus',checkIdle);
$('logout').onclick=()=>logoutSession();
async function persistRecord(n,v){try{const {error}=await db.rpc('guardar_record',{p_token:sessionToken,p_modo:String(n),p_wpm:v});if(error)throw error;if(!await loadProfile()){needAuth('Tu sesión expiró. Inicia sesión de nuevo.');return}refreshLeaderboard();if(screen==='results')$('summary').innerHTML+=' <p>Mejor marca guardada: '+best(n)+' WPM</p>'}catch{notice('Sin conexión: récord guardado en este dispositivo.')}}
showScreen('auth');if(sessionToken)loadProfile().then(ok=>ok?showScreen('menu'):needAuth()).catch(()=>needAuth('No pudimos validar la sesión. Intenta iniciar sesión.'));

async function refreshLeaderboard(){const box=$('leaderboard');if(!box)return;box.hidden=true;if(!profile||!sessionToken)return;const user=profile.username,token=sessionToken,selected=$('duration').value;try{const {data,error}=await db.rpc('top_global',{p_token:token,p_modo:selected});if(error||!data?.length||token!==sessionToken||selected!==$('duration').value)return;box.innerHTML='<h3>Top 5 global</h3><p class="micro">Mejor marca · '+selected+' segundos</p>'+data.map((p,i)=>'<div class="leader-row '+(p.username===user?'mine ':'')+(i===5?'separated':'')+'"><b>#'+p.posicion+'</b><span>'+esc(p.username)+(p.username===user?' · tú':'')+'</span><strong>'+Number(p.mejor_wpm)+' WPM</strong></div>').join('');box.hidden=false}catch{box.hidden=true}}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
